 @Transactional("pmsDBTransactionManager") public CaseView create(CaseRequest r){
  if(!Boolean.TRUE.equals(r.consent())||r.coverStartDate()!=null&&r.coverStartDate().isBefore(LocalDate.now()))throw invalid();
  validateProposal(r.productCode(),r.subjectType(),r.proposalData());
  Map<String,Object> normalizedProposal=normalizedProposal(r.productCode(),r.proposalData());String proposalJson=proposalJson(normalizedProposal);if(proposalJson.length()>100_000)throw invalid();
  InsuranceCase c=new InsuranceCase();c.setAgencyId(agencyEntity().getId());c.setCustomerUserId(uid());c.setReference(ref("INS"));c.setProductCode(r.productCode());
  c.setStatus("SUBMITTED");c.setFullName(r.fullName().trim());c.setEmail(r.email().trim().toLowerCase(Locale.ROOT));c.setPhone(r.phone().trim());c.setSubjectType(r.subjectType());
  c.setSubjectDescription(r.subjectDescription().trim());c.setSumInsured(calculatedSumInsured(r.productCode(),normalizedProposal));c.setCurrency(r.currency());c.setCoverStartDate(r.coverStartDate());
  c.setRiskDetails(StringUtils.trimToNull(r.riskDetails()));c.setProposalDataJson(proposalJson);c.setConsentAt(LocalDateTime.now());c.setSubmittedAt(LocalDateTime.now());stamp(c);caseRepo.save(c);activity(c.getId(),null,"CASE_SUBMITTED",null,c.getStatus(),null);notifyEmail(c.getEmail(),NotificationType.INSURANCE_APPLICATION_EMAIL,c.getReference());String agencyEmail=agencyEntity().getSupportEmail();if(StringUtils.isNotBlank(agencyEmail))notifyEmail(agencyEmail,NotificationType.INSURANCE_NEW_PROPOSAL_EMAIL,c.getReference(),c.getProductCode());return view(c);
 }
